extensionAttribute.scriptContentsMac:
#!/bin/zsh
# Updated by SecurityShrimp 2026 # Sophos AV Primary Update Server Extension Attribute # Targets macOS 12 through 26 (Tahoe), Intel and Apple Silicon
url=$(/usr/bin/defaults read /Library/Preferences/com.sophos.sau PrimaryServerURL 2>/dev/null) echo "<result>${url:-Not Set}</result>"
